// Shared helpers for the Node tests: the committed fixtures, a tiny PDF builder and error checks.
// Not a test file itself (the runner picks up `*.test.mjs` only).

import assert from 'node:assert/strict'
import { readFileSync, readdirSync } from 'node:fs'

import { FolioxideError } from 'folioxide'

/** `fixtures/syntax/` at the repository root: files generated by `cargo xtask fixtures`. */
export const SYNTAX_FIXTURES = new URL('../../../fixtures/syntax/', import.meta.url)

/** The names of the committed syntax fixtures, sorted. */
export function syntaxFixtureNames() {
  return readdirSync(SYNTAX_FIXTURES)
    .filter((name) => name.endsWith('.pdf'))
    .sort()
}

/** The bytes of a committed syntax fixture, as a Buffer. */
export function syntaxFixture(name) {
  return readFileSync(new URL(name, SYNTAX_FIXTURES))
}

/** Fixtures that do not open (encryption arrives in M5), with the code opening throws. */
export const ENCRYPTED = {
  'encrypted.pdf': 'E_PASSWORD_REQUIRED',
  'encrypted-unknown-handler.pdf': 'E_UNSUPPORTED',
}

/**
 * Fixtures whose cross-reference structure opening repairs: an incremental update to them is
 * refused (`E_UNSUPPORTED`, ARCHITECTURE §A.3 "Incremental save"), a full save works.
 */
export const REPAIRED = [
  'missing-xref-with-trailer.pdf',
  'missing-xref.pdf',
  'prev-loop.pdf',
  'startxref-off-by-n.pdf',
  'xref-offsets-off-by-n.pdf',
  'xref-subsection-starts-at-1.pdf',
]

/** Page counts that are not 1 (fixtures/README.md lists them). */
export const PAGE_COUNTS = { 'multi-revision.pdf': 2 }

/** The `DiagnosticKind` names `index.d.ts` declares (the Rust tests keep them complete). */
export function declaredDiagnosticKinds() {
  const dts = readFileSync(new URL('../index.d.ts', import.meta.url), 'utf8')
  const union = dts.split('export type DiagnosticKind =')[1]?.split('\n\n')[0]
  assert.ok(union, 'index.d.ts declares DiagnosticKind')
  return new Set([...union.matchAll(/'([a-zA-Z]+)'/g)].map((match) => match[1]))
}

/**
 * A PDF file with a classic cross-reference table. `objects` are the bodies of objects 1, 2, …
 * (strings, or `{ dict, data }` for a stream whose `/Length` is filled in); object 1 must be the
 * catalog.
 */
export function buildPdf(objects, { header = '%PDF-1.7' } = {}) {
  const parts = [Buffer.from(`${header}\n%\xE2\xE3\xCF\xD3\n`, 'latin1')]
  let length = parts[0].length
  const offsets = []
  const push = (chunk) => {
    const buffer = typeof chunk === 'string' ? Buffer.from(chunk, 'latin1') : chunk
    parts.push(buffer)
    length += buffer.length
  }
  objects.forEach((body, i) => {
    offsets.push(length)
    push(`${i + 1} 0 obj\n`)
    if (typeof body === 'string') {
      push(body)
    } else {
      push(`<< ${body.dict ?? ''} /Length ${body.data.length} >>\nstream\n`)
      push(body.data)
      push('\nendstream')
    }
    push('\nendobj\n')
  })
  const xref = length
  push(`xref\n0 ${objects.length + 1}\n0000000000 65535 f \n`)
  for (const offset of offsets) {
    push(`${String(offset).padStart(10, '0')} 00000 n \n`)
  }
  push(`trailer\n<< /Size ${objects.length + 1} /Root 1 0 R >>\nstartxref\n${xref}\n%%EOF\n`)
  return Buffer.concat(parts)
}

/** A one-page document whose page has an uncompressed content stream of `size` noisy bytes. */
export function largeDocument(size) {
  const data = Buffer.alloc(size)
  let state = 0x2545f491
  for (let i = 0; i < size; i++) {
    // xorshift32: deterministic bytes that Flate cannot squeeze much.
    state ^= state << 13
    state ^= state >>> 17
    state ^= state << 5
    data[i] = state & 0xff
  }
  return buildPdf([
    '<< /Type /Catalog /Pages 2 0 R >>',
    '<< /Type /Pages /Kids [3 0 R] /Count 1 >>',
    '<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R >>',
    { data },
  ])
}

/** Asserts `err` is a FolioxideError whose code is one of `codes` (a string or an array). */
export function assertCode(err, codes) {
  const expected = Array.isArray(codes) ? codes : [codes]
  assert.ok(err instanceof FolioxideError, `expected a FolioxideError, got ${err?.constructor?.name}: ${err}`)
  assert.ok(err instanceof Error)
  assert.equal(err.name, 'FolioxideError')
  assert.ok(expected.includes(err.code), `code ${err.code} (${err.message}) is not one of ${expected}`)
  assert.equal(typeof err.message, 'string')
  assert.ok(err.message.length > 0)
  return true
}

/** Asserts that `fn()` throws a FolioxideError with one of `codes`. */
export function assertThrowsCode(fn, codes) {
  assert.throws(fn, (err) => assertCode(err, codes))
}

/** Asserts that `promise` rejects with a FolioxideError with one of `codes`. */
export async function assertRejectsCode(promise, codes) {
  await assert.rejects(promise, (err) => assertCode(err, codes))
}

/** Whether `bytes` starts with `prefix`, compared with Buffer.compare. */
export function startsWithBytes(bytes, prefix) {
  return bytes.length >= prefix.length && Buffer.compare(bytes.subarray(0, prefix.length), prefix) === 0
}
